/**
 * Resource handler for the `text` asset type. Loads a file as a string.
 *
 * @category Asset
 */
export class TextHandler extends ResourceHandler {
    /**
     * Create a new TextHandler instance.
     *
     * @param {AppBase} app - The running {@link AppBase}.
     * @ignore
     */
    constructor(app: AppBase);
    /**
     * TextDecoder for decoding binary data.
     *
     * @type {TextDecoder|null}
     * @private
     */
    private decoder;
    /**
     * Parses raw DataView and returns string.
     *
     * @param {DataView} data - The raw data as a DataView
     * @returns {string} The parsed resource data.
     * @ignore
     */
    openBinary(data: DataView): string;
}
import { ResourceHandler } from './handler.js';
import type { AppBase } from '../app-base.js';
